using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        // Concrete subclass for testing abstract Person
        private class TestPerson : Person { }

        [Fact]
        public void FullName_WithBothNames_ReturnsLastCommaFirst()
        {
            // Arrange
            var person = new TestPerson { LastName = "Smith", FirstMidName = "John" };

            // Act
            var result = person.FullName;

            // Assert
            Assert.Equal("Smith, John", result);
        }

        [Fact]
        public void FullName_WithEmptyFirstName_ReturnsLastCommaEmpty()
        {
            // Arrange
            var person = new TestPerson { LastName = "Smith", FirstMidName = "" };

            // Act
            var result = person.FullName;

            // Assert
            Assert.Equal("Smith, ", result);
        }

        [Fact]
        public void ID_CanBeSetAndRetrieved()
        {
            // Arrange & Act
            var person = new TestPerson { ID = 42 };

            // Assert
            Assert.Equal(42, person.ID);
        }
    }

    public class StudentTests
    {
        [Fact]
        public void Student_InheritsFromPerson_HasFullName()
        {
            // Arrange
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "Jane",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            // Assert
            Assert.Equal("Doe, Jane", student.FullName);
            Assert.Equal(new DateTime(2023, 9, 1), student.EnrollmentDate);
        }

        [Fact]
        public void Student_Enrollments_DefaultsToNull()
        {
            var student = new Student();
            Assert.Null(student.Enrollments);
        }

        [Fact]
        public void Student_Enrollments_CanBeInitialized()
        {
            // Arrange
            var student = new Student
            {
                Enrollments = new List<Enrollment>
                {
                    new Enrollment { EnrollmentID = 1, CourseID = 100 },
                    new Enrollment { EnrollmentID = 2, CourseID = 200 }
                }
            };

            // Assert
            Assert.Equal(2, student.Enrollments.Count);
        }
    }

    public class InstructorTests
    {
        [Fact]
        public void Instructor_InheritsFromPerson_HasHireDate()
        {
            // Arrange
            var instructor = new Instructor
            {
                LastName = "Prof",
                FirstMidName = "Test",
                HireDate = new DateTime(2000, 3, 15)
            };

            // Assert
            Assert.Equal("Prof, Test", instructor.FullName);
            Assert.Equal(new DateTime(2000, 3, 15), instructor.HireDate);
        }

        [Fact]
        public void Instructor_CourseAssignments_CanBePopulated()
        {
            var instructor = new Instructor
            {
                CourseAssignments = new List<CourseAssignment>
                {
                    new CourseAssignment { CourseID = 1, InstructorID = 1 }
                }
            };

            Assert.Single(instructor.CourseAssignments);
            Assert.Equal(1, instructor.CourseAssignments.First().CourseID);
        }

        [Fact]
        public void Instructor_OfficeAssignment_CanBeSet()
        {
            var instructor = new Instructor
            {
                ID = 5,
                OfficeAssignment = new OfficeAssignment { InstructorID = 5, Location = "Room 101" }
            };

            Assert.NotNull(instructor.OfficeAssignment);
            Assert.Equal("Room 101", instructor.OfficeAssignment.Location);
            Assert.Equal(5, instructor.OfficeAssignment.InstructorID);
        }
    }

    public class CourseTests
    {
        [Fact]
        public void Course_Properties_SetCorrectly()
        {
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1
            };

            Assert.Equal(1050, course.CourseID);
            Assert.Equal("Chemistry", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
        }

        [Fact]
