using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Constructor_SetsPageIndexAndTotalPages()
        {
            // Arrange - 25 total items, page 2, 10 per page = 3 total pages
            var items = Enumerable.Range(11, 10).ToList();

            // Act
            var list = new PaginatedList<int>(items, 25, 2, 10);

            // Assert
            Assert.Equal(2, list.PageIndex);
            Assert.Equal(3, list.TotalPages);
            Assert.Equal(10, list.Count);
        }

        [Fact]
        public void Constructor_CalculatesTotalPages_RoundsUp()
        {
            // 21 items, page size 10 => ceil(21/10) = 3 total pages
            var items = new List<int> { 1 };
            var list = new PaginatedList<int>(items, 21, 1, 10);

            Assert.Equal(3, list.TotalPages);
        }

        [Fact]
        public void Constructor_SinglePage_TotalPagesIsOne()
        {
            var items = Enumerable.Range(1, 5).ToList();
            var list = new PaginatedList<int>(items, 5, 1, 10);

            Assert.Equal(1, list.TotalPages);
        }

        [Fact]
        public void Constructor_ExactMultiple_CorrectTotalPages()
        {
            // 20 items / 10 per page = exactly 2 pages
            var items = new List<int> { 1 };
            var list = new PaginatedList<int>(items, 20, 1, 10);

            Assert.Equal(2, list.TotalPages);
        }

        [Fact]
        public void HasPreviousPage_OnFirstPage_ReturnsFalse()
        {
            var list = new PaginatedList<int>(new List<int>(), 30, 1, 10);
            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_OnSecondPage_ReturnsTrue()
        {
            var list = new PaginatedList<int>(new List<int>(), 30, 2, 10);
            Assert.True(list.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_OnLastPage_ReturnsFalse()
        {
            var list = new PaginatedList<int>(new List<int>(), 30, 3, 10);
            Assert.False(list.HasNextPage);
        }

        [Fact]
        public void HasNextPage_OnFirstPageWithMultiplePages_ReturnsTrue()
        {
            var list = new PaginatedList<int>(new List<int>(), 30, 1, 10);
            Assert.True(list.HasNextPage);
        }

        [Fact]
        public void HasNextPage_OnMiddlePage_ReturnsTrue()
        {
            var list = new PaginatedList<int>(new List<int>(), 30, 2, 10);
            Assert.True(list.HasNextPage);
        }

        [Fact]
        public void Create_ReturnsCorrectPage()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act - page 2, size 10 => items 11-20
            var result = PaginatedList<int>.Create(source, 2, 10);

            // Assert
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
            Assert.Equal(10, result.Count);
            Assert.Equal(11, result[0]);
            Assert.Equal(20, result[9]);
        }

        [Fact]
        public void Create_LastPage_ReturnsRemainingItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act - page 3, size 10 => items 21-25
            var result = PaginatedList<int>.Create(source, 3, 10);

            // Assert
            Assert.Equal(5, result.Count);
            Assert.Equal(21, result[0]);
            Assert.Equal(25, result[4]);
        }

        [Fact]
        public void Create_FirstPage_ReturnsFirstItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(1, result.PageIndex);
            Assert.Equal(1, result[0]);
            Assert.Equal(10, result[9]);
            Assert.True(result.HasNextPage);
            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void Create_SingleItem_WorksCorrectly()
        {
            var source = new List<int> { 42 }.AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(1, result.Count);
            Assert.Equal(42, result[0]);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var source = Enumerable.Empty<int>().AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
        }

        [Fact]
        public void Items_AreAccessibleViaIndexer()
        {
            var items = new List<string> { "alpha", "beta", "gamma" };
            var list = new PaginatedList<string>(items, 3, 1, 10);

            Assert.Equal("alpha", list[0]);
            Assert.Equal("beta", list[1]);
            Assert.Equal("gamma", list[2]);
        }
    }
}

