            Assert.IsType<NotFoundResult>(result);
        }

        // === DeleteConfirmed ===

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesInstructorAndRedirects()
        {
            // Use the second instructor (Fakhouri) who is NOT a department admin
            var instructor = _context.Instructors.First(i => i.LastName == "Fakhouri");
            var initialCount = _context.Instructors.Count();

            var result = _controller.DeleteConfirmed(instructor.ID) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Equal(initialCount - 1, _context.Instructors.Count());
        }

        [Fact]
        public void DeleteConfirmed_InstructorIsDepartmentAdmin_NullsOutDepartmentInstructorID()
        {
            var instructor = _context.Instructors.First(i => i.LastName == "Abercrombie");
            var deptId = _context.Departments.First().DepartmentID;

            _controller.DeleteConfirmed(instructor.ID);

            var dept = _context.Departments.Find(deptId);
            Assert.Null(dept.InstructorID);
        }
    }
}

