            var result = person.FullName;

            Assert.Equal("Smith, John", result);
        }

        [Fact]
        public void FullName_WithEmptyFirstName_ReturnsLastCommaEmpty()
        {
            var person = new TestPerson { LastName = "Smith", FirstMidName = "" };

            Assert.Equal("Smith, ", person.FullName);
        }

        [Fact]
        public void FullName_DifferentNames_FormatsCorrectly()
        {
            var person = new TestPerson { LastName = "O'Brien", FirstMidName = "Mary Jane" };

            Assert.Equal("O'Brien, Mary Jane", person.FullName);
        }

        [Fact]
        public void ID_CanBeSetAndRetrieved()
        {
            var person = new TestPerson { ID = 42 };
            Assert.Equal(42, person.ID);
        }
    }

    public class StudentTests
    {
        [Fact]
        public void Student_InheritsFromPerson_HasFullName()
        {
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "Jane",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            Assert.Equal("Doe, Jane", student.FullName);
            Assert.Equal(new DateTime(2023, 9, 1), student.EnrollmentDate);
        }

