+using System;
+using ContosoUniversity.Models;
+using ContosoUniversity.Services;
+using Xunit;
+
+namespace ContosoUniversity.Tests.Services
+{
+    public class NotificationServiceTests : IDisposable
+    {
+        private readonly NotificationService _sut;
+
+        public NotificationServiceTests()
+        {
+            _sut = new NotificationService();
+            // Drain the static queue to start clean
+            while (_sut.ReceiveNotification() != null) { }
+        }
+
+        public void Dispose()
+        {
+            _sut.Dispose();
+        }
+
+        [Fact]
+        public void SendNotification_WithDisplayName_EnqueuesNotification()
+        {
+            _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "Admin");
+
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Student", notification.EntityType);
+            Assert.Equal("42", notification.EntityId);
+            Assert.Equal("CREATE", notification.Operation);
+            Assert.Equal("Admin", notification.CreatedBy);
+            Assert.False(notification.IsRead);
+            Assert.Contains("John Doe", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
+        {
+            _sut.SendNotification("Course", "101", EntityOperation.UPDATE, "System");
+
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Contains("ID: 101", notification.Message);
+            Assert.Equal("UPDATE", notification.Operation);
+        }
+
+        [Fact]
+        public void SendNotification_WithoutUserName_DefaultsToSystem()
+        {
+            _sut.SendNotification("Student", "1", EntityOperation.CREATE);
+
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("System", notification.CreatedBy);
+        }
+
+        [Theory]
+        [InlineData(EntityOperation.CREATE, "has been created")]
+        [InlineData(EntityOperation.UPDATE, "has been updated")]
+        [InlineData(EntityOperation.DELETE, "has been deleted")]
+        public void SendNotification_GeneratesCorrectMessage_ForOperation(EntityOperation operation, string expectedFragment)
+        {
+            _sut.SendNotification("Department", "5", "Engineering", operation, "Admin");
+
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Contains(expectedFragment, notification.Message);
+            Assert.Contains("Engineering", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_CreateOperation_ExactMessageFormat()
+        {
+            _sut.SendNotification("Student", "1", "Jane Smith", EntityOperation.CREATE, "Admin");
+
+            var notification = _sut.ReceiveNotification();
+            Assert.Equal("New Student 'Jane Smith' has been created", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_UpdateOperation_ExactMessageFormat()
+        {
+            _sut.SendNotification("Course", "100", "Math 101", EntityOperation.UPDATE, "Admin");
+
+            var notification = _sut.ReceiveNotification();
+            Assert.Equal("Course 'Math 101' has been updated", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_DeleteOperation_ExactMessageFormat()
+        {
+            _sut.SendNotification("Department", "3", "Physics", EntityOperation.DELETE, "Admin");
+
+            var notification = _sut.ReceiveNotification();
+            Assert.Equal("Department 'Physics' has been deleted", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_NullDisplayName_FallsBackToId()
+        {
+            _sut.SendNotification("Student", "7", null, EntityOperation.CREATE, "Admin");
+
+            var notification = _sut.ReceiveNotification();
+            Assert.Equal("New Student (ID: 7) has been created", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_WhitespaceDisplayName_FallsBackToId()
+        {
+            _sut.SendNotification("Student", "7", "  ", EntityOperation.UPDATE, "Admin");
+
+            var notification = _sut.ReceiveNotification();
+            Assert.Contains("ID: 7", notification.Message);
+        }
+
+        [Fact]
+        public void ReceiveNotification_WhenQueueIsEmpty_ReturnsNull()
+        {
+            var result = _sut.ReceiveNotification();
+            Assert.Null(result);
+        }
+
+        [Fact]
+        public void ReceiveNotification_ReturnsInFifoOrder()
+        {
+            _sut.SendNotification("A", "1", EntityOperation.CREATE);
+            _sut.SendNotification("B", "2", EntityOperation.UPDATE);
+            _sut.SendNotification("C", "3", EntityOperation.DELETE);
+
+            var first = _sut.ReceiveNotification();
+            var second = _sut.ReceiveNotification();
+            var third = _sut.ReceiveNotification();
+
+            Assert.Equal("A", first.EntityType);
+            Assert.Equal("B", second.EntityType);
+            Assert.Equal("C", third.EntityType);
+        }
+
+        [Fact]
+        public void ReceiveNotification_RemovesFromQueue()
+        {
+            _sut.SendNotification("X", "1", EntityOperation.CREATE);
+
+            var first = _sut.ReceiveNotification();
+            var second = _sut.ReceiveNotification();
+
+            Assert.NotNull(first);
+            Assert.Null(second);
+        }
+
+        [Fact]
+        public void MarkAsRead_DoesNotThrow()
+        {
+            var exception = Record.Exception(() => _sut.MarkAsRead(42));
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void SendNotification_SetsCreatedAt()
+        {
+            var before = DateTime.Now;
+            _sut.SendNotification("Test", "1", EntityOperation.CREATE);
+            var after = DateTime.Now;
+
+            var notification = _sut.ReceiveNotification();
+            Assert.InRange(notification.CreatedAt, before, after);
+        }
+
+        [Fact]
+        public void SendNotification_SetsIsReadToFalse()
+        {
+            _sut.SendNotification("Test", "1", EntityOperation.CREATE);
+
+            var notification = _sut.ReceiveNotification();
+            Assert.False(notification.IsRead);
+        }
+
+        [Fact]
+        public void Dispose_CanBeCalledMultipleTimes()
+        {
+            var service = new NotificationService();
+            var exception = Record.Exception(() =>
+            {
+                service.Dispose();
+                service.Dispose();
+            });
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void SendNotification_TwoArgOverload_PassesNullDisplayName()
+        {
+            _sut.SendNotification("Instructor", "10", EntityOperation.DELETE, "Admin");
+
+            var notification = _sut.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Contains("ID: 10", notification.Message);
+            Assert.Equal("DELETE", notification.Operation);
+        }
+
+        [Fact]
+        public void SendNotification_WithoutDisplayNameNoUser_DefaultsBoth()
+        {
+            _sut.SendNotification("Test", "99", EntityOperation.UPDATE);
+
+            var notification = _sut.ReceiveNotification();
+            Assert.Equal("System", notification.CreatedBy);
+            Assert.Contains("ID: 99", notification.Message);
+            Assert.Contains("has been updated", notification.Message);
+        }
+    }
+}
