+using ContosoUniversity.Tests.Helpers;
+using Xunit;
+
+namespace ContosoUniversity.Tests.Controllers
+{
+    public class BaseControllerTests : IDisposable
+    {
+        private readonly SchoolContext _context;
+        private readonly TestableBaseController _controller;
+
+        private class TestableBaseController : BaseController
+        {
+            public TestableBaseController(SchoolContext context) : base(context) { }
+
+            public void InvokeSendEntityNotification(string entityType, string entityId, EntityOperation operation)
+            {
+                SendEntityNotification(entityType, entityId, operation);
+            }
+
+            public void InvokeSendEntityNotification(string entityType, string entityId, string displayName, EntityOperation operation)
+            {
+                SendEntityNotification(entityType, entityId, displayName, operation);
+            }
+
+            public void InvokeDispose()
+            {
+                Dispose(true);
+            }
+        }
+
+        public BaseControllerTests()
+        {
+            _context = TestDbContextFactory.Create();
+            _controller = new TestableBaseController(_context);
+        }
+
+        public void Dispose()
+        {
+            _controller.Dispose();
+            _context.Dispose();
+        }
+
+        [Fact]
+        public void SendEntityNotification_ThreeArgOverload_DoesNotThrow()
+        {
+            var exception = Record.Exception(() =>
+                _controller.InvokeSendEntityNotification("Student", "1", EntityOperation.CREATE));
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void SendEntityNotification_FourArgOverload_DoesNotThrow()
+        {
+            var exception = Record.Exception(() =>
+                _controller.InvokeSendEntityNotification("Student", "1", "John Doe", EntityOperation.UPDATE));
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void SendEntityNotification_NullDisplayName_DoesNotThrow()
+        {
+            var exception = Record.Exception(() =>
+                _controller.InvokeSendEntityNotification("Course", "42", null, EntityOperation.DELETE));
+            Assert.Null(exception);
+        }
+
+        [Theory]
+        [InlineData(EntityOperation.CREATE)]
+        [InlineData(EntityOperation.UPDATE)]
+        [InlineData(EntityOperation.DELETE)]
+        public void SendEntityNotification_AllOperations_DoNotThrow(EntityOperation operation)
+        {
+            var exception = Record.Exception(() =>
+                _controller.InvokeSendEntityNotification("Entity", "1", "Name", operation));
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void Dispose_CanBeCalledMultipleTimes()
+        {
+            var controller = new TestableBaseController(TestDbContextFactory.Create());
+            var exception = Record.Exception(() =>
+            {
+                controller.InvokeDispose();
+                controller.InvokeDispose();
+            });
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void Constructor_SetsDbContext_OperationsDoNotThrowNRE()
+        {
+            // Verify the controller is functional (db is set)
+            var exception = Record.Exception(() =>
+                _controller.InvokeSendEntityNotification("Test", "1", EntityOperation.CREATE));
+            Assert.Null(exception);
+        }
+    }
+}
